(** ** What this board establishes

    15 of 15 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 15 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    0 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_0RB1LA_1RC0LA_1LB1RD_1LA1RB : list (LRule * list rstep) :=
  [].
Definition nrules_0RB1LA_1RC0LA_1LB1RD_1LA1RB : list LRule := map fst nlad_0RB1LA_1RC0LA_1LB1RD_1LA1RB.
Local Notation nrules := nrules_0RB1LA_1RC0LA_1LB1RD_1LA1RB.

Lemma nladder_ok_0RB1LA_1RC0LA_1LB1RD_1LA1RB : check_ladder tm [] nlad_0RB1LA_1RC0LA_1LB1RD_1LA1RB = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_0RB1LA_1RC0LA_1LB1RD_1LA1RB : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_0RB1LA_1RC0LA_1LB1RD_1LA1RB. Qed.

Definition iarm0_0_0RB1LA_1RC0LA_1LB1RD_1LA1RB : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]))
          (mkC StB (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0])) 0 1.
Definition ch_iarm0_0_0RB1LA_1RC0LA_1LB1RD_1LA1RB : list nseg :=
  [NCh [RB (SCycR 3);RB (SWin 6);RB (SCycL 3 0);RB (SWinL 4)]].
Lemma ok_iarm0_0_0RB1LA_1RC0LA_1LB1RD_1LA1RB :
  check_narm tm true false nrules iarm0_0_0RB1LA_1RC0LA_1LB1RD_1LA1RB ch_iarm0_0_0RB1LA_1RC0LA_1LB1RD_1LA1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_0RB1LA_1RC0LA_1LB1RD_1LA1RB : LRule :=
