  [NCh [RB (SWin 3);RB (SCycR 3);RB (SWinR 2);RB (SRotL 1);RB (SWin 1);RB (SCycL 3 0);RB (SWin 2);RB (SWinL 4);RB (SUnrotR 2)]].
