  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S1;S1] [S1;S1] 1 0 [])) 0 1.
