  [NCh [RB (SWin 2);RB (SCycR 2);RB (SWinR 4);RB (SCycL 2 0);RB (SWin 2);RB (SWinL 1);RB (SRotR 1)]].
Lemma ok_farm1_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA :
  check_narm tm true true nrules farm1_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA ch_farm1_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB1LD_1RC0RA_0LA1RB_0LA1LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA
  | 0, 1 => iarm0_1_0RB1LD_1RC0RA_0LA1RB_0LA1LA
  | _, _ => iarm0_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_0RB1LD_1RC0RA_0LA1RB_0LA1LA (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA
  | _, _ => farm1_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB1LD_1RC0RA_0LA1RB_0LA1LA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_0RB1LD_1RC0RA_0LA1RB_0LA1LA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_0RB1LD_1RC0RA_0LA1RB_0LA1LA (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 0]
  | 1, (StA, S1) => [SWin 2;SCycR 2;SWinR 3]
  | 1, (StB, S0) => [SWin 1]
  | 1, (StB, S1) => [SWin 2;SCycR 2;SWinR 4;SCycL 2 0;SWinL 6]
  | 1, (StC, S0) => [SWin 2;SCycR 2;SWinR 2]
  | 1, (StC, S1) => [SWin 2]
  | 1, (StD, S0) => [SWin 2;SCycR 2;SWinR 4;SCycL 2 0;SWin 2]
  | 1, (StD, S1) => [SWin 2;SCycR 2;SWinR 4]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_0RB1LD_1RC0RA_0LA1RB_0LA1LA (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | _, _ => []
  end.

Lemma iarm_reach_0RB1LD_1RC0RA_0LA1RB_0LA1LA : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_0RB1LD_1RC0RA_0LA1RB_0LA1LA d r)) (lr_rhs (iarm_0RB1LD_1RC0RA_0LA1RB_0LA1LA d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_0RB1LD_1RC0RA_0LA1RB_0LA1LA | exact ok_iarm0_0_0RB1LD_1RC0RA_0LA1RB_0LA1LA]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_0RB1LD_1RC0RA_0LA1RB_0LA1LA | exact ok_iarm0_1_0RB1LD_1RC0RA_0LA1RB_0LA1LA]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_lhs_0RB1LD_1RC0RA_0LA1RB_0LA1LA : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 ->
  lr_lhs (iarm_0RB1LD_1RC0RA_0LA1RB_0LA1LA d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 1 1 r) [d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_rhs_0RB1LD_1RC0RA_0LA1RB_0LA1LA : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 ->
  lr_rhs (iarm_0RB1LD_1RC0RA_0LA1RB_0LA1LA d r)
    = cls_conf FAM (cls_side FAM [] 0 r (astride 1 1 r) [S d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma farm_reach_0RB1LD_1RC0RA_0LA1RB_0LA1LA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_0RB1LD_1RC0RA_0LA1RB_0LA1LA r ph)) (lr_rhs (farm_0RB1LD_1RC0RA_0LA1RB_0LA1LA r ph)).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
