  | 1, (StB, S0) => [SWin 3;SCycR 3;SWinR 6]
  | 1, (StB, S1) => [SWin 2]
  | 1, (StC, S0) => []
  | 1, (StC, S1) => [SWin 3;SCycR 3;SWinR 7]
  | 1, (StD, S0) => [SWin 3;SCycR 3;SWinR 3]
  | 1, (StD, S1) => [SWin 3]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
