    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0LD_0RC1LD_1RD0RA_1LB1RC : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0LD_0RC1LD_1RD0RA_1LB1RC pins_1RB0LD_0RC1LD_1RD0RA_1LB1RC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LD_0RC1LD_1RD0RA_1LB1RC : Fam := mkFam 2 [[S1;S1];[S1;S0]] [] [[]] Binary 1 [mkFill 2 [] 0 [1] 0] StB S0 false [].
Local Notation FAM := fam_1RB0LD_0RC1LD_1RD0RA_1LB1RC.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LD_0RC1LD_1RD0RA_1LB1RC : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S0;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 4, [RB (SWin 4)]);
   (mkLRule (mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB0LD_0RC1LD_1RD0RA_1LB1RC.

Definition rules_1RB0LD_0RC1LD_1RD0RA_1LB1RC : list LRule := map fst lad.
Local Notation rules := rules_1RB0LD_0RC1LD_1RD0RA_1LB1RC.

Lemma ladder_ok_1RB0LD_0RC1LD_1RD0RA_1LB1RC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LD_0RC1LD_1RD0RA_1LB1RC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LD_0RC1LD_1RD0RA_1LB1RC. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
