Definition ch_arm15_1RB0LD_0RC1LD_1RD0RA_1LB1RC : list rstep := [RB (SWin 4)].
Lemma ok_arm15_1RB0LD_0RC1LD_1RD0RA_1LB1RC :
  check_arm tm true true rules arm15_1RB0LD_0RC1LD_1RD0RA_1LB1RC ch_arm15_1RB0LD_0RC1LD_1RD0RA_1LB1RC = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm15_1RB0LD_0RC1LD_1RD0RA_1LB1RC : RuleSound tm true true arm15_1RB0LD_0RC1LD_1RD0RA_1LB1RC.
