Qed.

Lemma farm_reach_1RB0RD_1RC1LD_0LB0RC_0LA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  ReachL tm true true (lr_lhs (farm_1RB0RD_1RC1LD_0LB0RC_0LA1LD r ph)) (lr_rhs (farm_1RB0RD_1RC1LD_0LB0RC_0LA1LD r ph)).
