  {
    destruct ph as [|ph].
    { eapply narm_reach; [exact nrules_sound_1RB0RD_1RC1LD_0LB0RC_0LA1LD | exact ok_farm1_0_1RB0RD_1RC1LD_0LB0RC_0LA1LD]. }
    destruct ph as [|ph].
    { eapply narm_reach; [exact nrules_sound_1RB0RD_1RC1LD_0LB0RC_0LA1LD | exact ok_farm1_1_1RB0RD_1RC1LD_0LB0RC_0LA1LD]. }
    exfalso; lia.
