Qed.

Lemma farm_lhs_1RB0RD_1RC1LD_0LB0RC_0LA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  lr_lhs (farm_1RB0RD_1RC1LD_0LB0RC_0LA1LD r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
Proof.
