  | 2, 0 => farm2_0_1RB1LB_1LC0RD_1LA1RA_0LA1RD
  | _, _ => farm1_0_1RB1LB_1LC0RD_1LA1RA_0LA1RD  (* unreachable: 0 < r < N0 + st *)
  end.

