  check_narm tm false true nrules iarm0_0_1RB1LC_0LC1RA_1LA0LD_1LB0RA ch_iarm0_0_1RB1LC_0LC1RA_1LA0LD_1LB0RA = true.
Proof. vm_compute. reflexivity. Qed.

