  [NCh [RB (SWin 3);RB (SCycL 3 0);RB (SWinL 2);RB (SRotR 1);RB (SWin 1);RB (SCycR 3);RB (SWin 2);RB (SWinR 4);RB (SUnrotL 2)]].
Lemma ok_farm1_0_1RB1LC_0LC1RB_1LD0RB_1RC1LA :
  check_narm tm true true nrules farm1_0_1RB1LC_0LC1RB_1LD0RB_1RC1LA ch_farm1_0_1RB1LC_0LC1RB_1LD0RB_1RC1LA = true.
Proof. vm_compute. reflexivity. Qed.

