(** 1RB1RA_1RC1LD_0LB0RC_0LA1LD *)
Definition tm_1RB1RA_1RC1LD_0LB0RC_0LA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StB
  | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DL StA
  | StD, S1 => mk S1 DL StD
  end.
(** the instructions the machine never fires; the whole board runs
