Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1RA_1RC1LD_0LB0RC_0LA1LD : LRule :=
  mkLRule (mkC StB (mkS [S1;S1] [S1;S1] 1 0 [S0;S1;S1]) S1 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S0;S0] [S0;S0] 1 0 [S0;S0;S0;S1;S1]) S1 (mkS [] [] 0 0 [])) 0 1.
