Qed.

Lemma farm_reach_1RB1RA_1RC1LD_0LB0RC_0LA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_1RB1RA_1RC1LD_0LB0RC_0LA1LD r ph)) (lr_rhs (farm_1RB1RA_1RC1LD_0LB0RC_0LA1LD r ph)).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { eapply narm_reach; [exact nrules_sound_1RB1RA_1RC1LD_0LB0RC_0LA1LD | exact ok_farm1_0_1RB1RA_1RC1LD_0LB0RC_0LA1LD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma farm_lhs_1RB1RA_1RC1LD_0LB0RC_0LA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_lhs (farm_1RB1RA_1RC1LD_0LB0RC_0LA1LD r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
