    [vm_compute].  A wrong chain makes the replay return [None] and this
    file fails to compile.

    The certificate's four PARAMETERS -- the fill law per phase with the
    phase it lands in, the terminator of each phase, the counter's code and
    its step per anchor visit -- arrive as fields of a [LadderFam.Fam]
    value, not as definitions in the kernel (LADDER_PLAN.md 4f).

    Axiom footprint: [functional_extensionality_dep], via [CTape.lift]. *)
Import Arith Lia Bool List.
Import BBB4_Statement CTape.
Import TNF_QH.
Import WTape LapGlueQuiet.
Import LapDecider LapAvoid LadderKernel LadderFam.
Import LadderCheck.
Import BBBT4_Statement.
Import WrapTr LadderCheckTr.
Import LapGlueTr.
Import LadderCheckLiftTr.
Import LadderNest LadderCheckNestTr.
Import ListNotations.

Definition mk_1RB1RB_1LC1RD_1LA1LC_0LB0RD (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1RB_1LC1RD_1LA1LC_0LB0RD.

(** 1RB1RB_1LC1RD_1LA1LC_0LB0RD *)
Definition tm_1RB1RB_1LC1RD_1LA1LC_0LB0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA
  | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DL StB
  | StD, S1 => mk S0 DR StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1RB_1LC1RD_1LA1LC_0LB0RD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1RB_1LC1RD_1LA1LC_0LB0RD pins_1RB1RB_1LC1RD_1LA1LC_0LB0RD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1RB_1LC1RD_1LA1LC_0LB0RD : Fam := mkFam 2 [[S0;S0];[S1;S1]] [] [[S1];[S0;S1;S1]] Binary 1 [mkFill 0 [] 0 [] 1;mkFill 1 [] 0 [1] 0] StB S0 true [].
Local Notation FAM := fam_1RB1RB_1LC1RD_1LA1LC_0LB0RD.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RB_1LC1RD_1LA1LC_0LB0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB1RB_1LC1RD_1LA1LC_0LB0RD.

Definition rules_1RB1RB_1LC1RD_1LA1LC_0LB0RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1RB_1LC1RD_1LA1LC_0LB0RD.

Lemma ladder_ok_1RB1RB_1LC1RD_1LA1LC_0LB0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RB_1LC1RD_1LA1LC_0LB0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RB_1LC1RD_1LA1LC_0LB0RD. Qed.

