          (mkC StB (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1RB_1LC1RD_1LA1LC_0LB0RD : list nseg :=
  [NCh [RB (SWin 4);RB (SWinR 2)]].
Lemma ok_iarm0_0_1RB1RB_1LC1RD_1LA1LC_0LB0RD :
