Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1RB_1LC1RD_1LA1LC_0LB0RD : LRule :=
  mkLRule (mkC StB (mkS [S1;S1] [S1;S1] 1 0 [S0;S0]) S0 (mkS [] [] 0 0 []))
