    The certificate's four PARAMETERS -- the fill law per phase with the
    phase it lands in, the terminator of each phase, the counter's code and
    its step per anchor visit -- arrive as fields of a [LadderFam.Fam]
    value, not as definitions in the kernel (LADDER_PLAN.md 4f).

    Axiom footprint: [functional_extensionality_dep], via [CTape.lift]. *)
Import Arith Lia Bool List.
Import BBB4_Statement CTape.
Import TNF_QH.
Import WTape LapGlueQuiet.
Import LapDecider LapAvoid LadderKernel LadderFam.
Import LadderCheck.
Import BBBT4_Statement.
Import WrapTr LadderCheckTr.
Import LapGlueTr.
Import LadderCheckLiftTr.
Import LadderNest LadderCheckNestTr.
Import ListNotations.

Definition mk_1RB1RC_1RC1RA_1LC0LD_0RB1LD (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1RC_1RC1RA_1LC0LD_0RB1LD.

(** 1RB1RC_1RC1RA_1LC0LD_0RB1LD *)
Definition tm_1RB1RC_1RC1RA_1LC0LD_0RB1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StC
  | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DR StB
  | StD, S1 => mk S1 DL StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1RC_1RC1RA_1LC0LD_0RB1LD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1RC_1RC1RA_1LC0LD_0RB1LD pins_1RB1RC_1RC1RA_1LC0LD_0RB1LD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1RC_1RC1RA_1LC0LD_0RB1LD : Fam := mkFam 3 [[S1;S1];[S1;S0];[S0;S1]] [] [[]] Binary 1 [mkFill 2 [] 0 [1;1] 0] StB S1 false [].
Local Notation FAM := fam_1RB1RC_1RC1RA_1LC0LD_0RB1LD.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RC_1RC1RA_1LC0LD_0RB1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1RC_1RC1RA_1LC0LD_0RB1LD.

Definition rules_1RB1RC_1RC1RA_1LC0LD_0RB1LD : list LRule := map fst lad.
Local Notation rules := rules_1RB1RC_1RC1RA_1LC0LD_0RB1LD.

Lemma ladder_ok_1RB1RC_1RC1RA_1LC0LD_0RB1LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RC_1RC1RA_1LC0LD_0RB1LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RC_1RC1RA_1LC0LD_0RB1LD. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
