  match r, ph with
  | 1, 0 => farm1_0_1RB1RC_1RC1RA_1LC0LD_0RB1LD
  | _, _ => farm1_0_1RB1RC_1RC1RA_1LC0LD_0RB1LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RC_1RC1RA_1LC0LD_0RB1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RC_1RC1RA_1LC0LD_0RB1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
