Module LDRT_1RB1RD_0LC1RA_0RB1LC_1LD0LC.
(** * LDRT_1RB1RD_0LC1RA_0RB1LC_1LD0LC: machine 1RB1RD_0LC1RA_0RB1LC_1LD0LC, boarded by the STAGE-B LADDER at the INSTRUCTION level
    ([NeverQuasiHaltsTr], through [LadderCheckTr]).

