    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RD_0LC1RA_0RB1LC_1LD0LC : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1RD_0LC1RA_0RB1LC_1LD0LC.

Definition rules_1RB1RD_0LC1RA_0RB1LC_1LD0LC : list LRule := map fst lad.
Local Notation rules := rules_1RB1RD_0LC1RA_0RB1LC_1LD0LC.

Lemma ladder_ok_1RB1RD_0LC1RA_0RB1LC_1LD0LC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RD_0LC1RA_0RB1LC_1LD0LC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RD_0LC1RA_0RB1LC_1LD0LC. Qed.

