Definition iarm_1RB1RD_1LC0RD_1LA1LB_0LB1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RD_1LC0RD_1LA1LB_0LB1RD
  | 0, 1 => iarm0_1_1RB1RD_1LC0RD_1LA1LB_0LB1RD
  | _, _ => iarm0_0_1RB1RD_1LC0RD_1LA1LB_0LB1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1RD_1LC0RD_1LA1LB_0LB1RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1RD_1LC0RD_1LA1LB_0LB1RD
  | 1, 1 => farm1_1_1RB1RD_1LC0RD_1LA1LB_0LB1RD
  | 1, 2 => farm1_2_1RB1RD_1LC0RD_1LA1LB_0LB1RD
  | 1, 3 => farm1_3_1RB1RD_1LC0RD_1LA1LB_0LB1RD
  | _, _ => farm1_0_1RB1RD_1LC0RD_1LA1LB_0LB1RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RD_1LC0RD_1LA1LB_0LB1RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 1, 1 => 1 | 1, 2 => 1 | 1, 3 => 1 | _, _ => 0 end.
Definition fm2_1RB1RD_1LC0RD_1LA1LB_0LB1RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | 1, 2 => 0 | 1, 3 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    2.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1RD_1LC0RD_1LA1LB_0LB1RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 2;SCycL 2 0;SWinL 3]
  | 1, (StA, S1) => [SWin 2;SCycL 2 0;SWin 3]
  | 1, (StB, S0) => [SWin 1]
  | 1, (StB, S1) => [SWin 2;SCycL 2 0;SWin 1]
  | 1, (StC, S0) => [SWin 2;SCycL 2 0;SWinL 2]
  | 1, (StC, S1) => [SWin 2]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 2;SCycL 2 0;SWin 2]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB1RD_1LC0RD_1LA1LB_0LB1RD (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | _, _ => []
  end.

(** The visit phase of each instruction ([LadderCheckNestPvTr]), and the
    fills it takes the phase cycle to reach it from each phase. *)
Definition pvf_1RB1RD_1LC0RD_1LA1LB_0LB1RD (t : Instr) : nat :=
  match t with
  | (StA, S0) => 2
  | (StA, S1) => 3
  | (StB, S0) => 0
  | (StB, S1) => 0
  | (StC, S0) => 2
  | (StC, S1) => 0
  | (StD, S0) => 0
  | (StD, S1) => 0
  end.

Definition kcyc_1RB1RD_1LC0RD_1LA1LB_0LB1RD (tg ph : nat) : nat :=
  match tg, ph with
  | 0, 0 => 0
